/**
 * One account on this device.
 */
public protocol MessengerClientProtocol: AnyObject, Sendable {
    
    func account() throws  -> AccountInfo?
    
    func addMembers(conversationId: String, usernames: [String]) throws 
    
    /**
     * Stops pushes to this device.
     */
    func clearPushTarget() throws 
    
    func confirmRecoveryKeySaved() throws 
    
    func conversations() throws  -> [ConversationSummary]
    
    func createGroup(title: String, usernames: [String]) throws  -> String
    
    /**
     * Leaves every conversation, deletes the account on the server (the
     * username becomes free) and erases this device. Afterwards the client
     * is empty, as on a fresh install.
     */
    func deleteAccount() throws 
    
    func deleteMessage(conversationId: String, messageId: String) throws 
    
    func editMessage(conversationId: String, messageId: String, text: String) throws 
    
    func leaveConversation(conversationId: String) throws 
    
    /**
     * Where we share our location now.
     */
    func locationShares() throws  -> [LocationShare]
    
    func markRead(conversationId: String) throws 
    
    /**
     * Marks a thread's replies read. `message_id` is the thread's first message.
     */
    func markThreadRead(conversationId: String, messageId: String) throws 
    
    func members(conversationId: String) throws  -> [MemberView]
    
    /**
     * The latest messages in the chat, oldest first; replies in threads are
     * counted under the message they hang off.
     */
    func messages(conversationId: String, limit: UInt32) throws  -> [MessageView]
    
    /**
     * Replaces the recovery key; the old one stops working. Show the new
     * one, then call `confirm_recovery_key_saved`.
     */
    func newRecoveryKey() throws  -> String
    
    func pendingRecoveryKey() throws  -> String?
    
    func privacySettings() throws  -> PrivacySettings
    
    /**
     * Our avatar and ink, if we've chosen them.
     */
    func profile() throws  -> Profile?
    
    /**
     * Everyone's avatar and ink that we know of, ours included.
     */
    func profiles() throws  -> [PersonProfile]
    
    /**
     * Whether the server can push to iPhones, and its VAPID key.
     */
    func pushInfo() throws  -> PushInfo
    
    /**
     * Where pushes for this device go now, if anywhere.
     */
    func pushTarget() throws  -> PushTarget?
    
    func react(conversationId: String, messageId: String, emoji: String?) throws 
    
    func recover(username: String, recoveryKey: String) throws  -> AccountInfo
    
    func register(username: String) throws  -> Registration
    
    /**
     * Leaves every conversation, withdraws this device's invitation keys and
     * erases this device. The account remains; the recovery key brings it
     * back on any device, without the old messages.
     */
    func removeFromDevice() throws 
    
    func removeMember(conversationId: String, username: String) throws 
    
    /**
     * Replies in the thread under `message_id` (or the thread it's in).
     */
    func replyInThread(conversationId: String, messageId: String, text: String) throws  -> String
    
    func safetyNumber(conversationId: String) throws  -> SafetyNumber
    
    func sendText(conversationId: String, text: String, replyTo: String?) throws  -> String
    
    func setPrivacySettings(settings: PrivacySettings) throws 
    
    /**
     * Sets our avatar and ink and shares them with every chat. Names are
     * lowercase letters, digits and dashes.
     */
    func setProfile(avatar: String, ink: String) throws 
    
    /**
     * Registers where to push this device. Call it whenever the platform
     * hands out a new token or endpoint.
     */
    func setPushTarget(target: PushTarget) throws 
    
    /**
     * Call as the draft changes: true while there's text, false when it's
     * cleared. Throttled; sending a message also ends it.
     */
    func setTyping(conversationId: String, typing: Bool) throws 
    
    /**
     * The latest position of everyone sharing their location with us.
     */
    func sharedLocations() throws  -> [SharedLocation]
    
    func startDirectChat(username: String) throws  -> String
    
    /**
     * Starts sharing our location in a conversation, or changes until when
     * (`until_ms` None: until stopped). Positions go out with `update_location`.
     */
    func startSharingLocation(conversationId: String, untilMs: Int64?) throws 
    
    /**
     * Stops sharing; the others forget our location as soon as they get this.
     */
    func stopSharingLocation(conversationId: String) throws 
    
    /**
     * Sends queued work and fetches new messages; waits up to `wait_ms`
     * for something to arrive.
     */
    func sync(waitMs: UInt32) throws  -> SyncReport
    
    /**
     * Incoming messages to show notifications for, each handed out once
     * (messages already read are skipped). Call after a sync.
     */
    func takeNotifications(limit: UInt32) throws  -> [MessageNotification]
    
    /**
     * A thread: its first message, then the latest `limit` replies, oldest first.
     */
    func threadMessages(conversationId: String, messageId: String, limit: UInt32) throws  -> [MessageView]
    
    /**
     * Who is typing in a conversation right now.
