public struct FfiConverterTypeMessengerClient: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = MessengerClient

    public static func lift(_ handle: UInt64) throws -> MessengerClient {
        return MessengerClient(unsafeFromHandle: handle)
    }

    public static func lower(_ value: MessengerClient) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> MessengerClient {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: MessengerClient, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


